import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Dhf_H6O0.js";const u=JSON.parse('{"title":"Data Directory","description":"","frontmatter":{},"headers":[],"relativePath":"settings/data-directory.md","filePath":"settings/data-directory.md"}'),i={name:"settings/data-directory.md"};function n(d,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="data-directory" tabindex="-1">Data Directory <a class="header-anchor" href="#data-directory" aria-label="Permalink to &quot;Data Directory&quot;">​</a></h1><p>MCPBehindIT stores all its data in a dedicated folder on your Mac. No data is stored inside the Docker container — everything persists between gateway restarts.</p><h2 id="location" tabindex="-1">Location <a class="header-anchor" href="#location" aria-label="Permalink to &quot;Location&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/Library/Application Support/MindBehind/mcp-orchestrator/</span></span></code></pre></div><p>On a typical Mac, this resolves to:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/Users/YourName/Library/Application Support/MindBehind/mcp-orchestrator/</span></span></code></pre></div><h2 id="opening-the-data-folder" tabindex="-1">Opening the data folder <a class="header-anchor" href="#opening-the-data-folder" aria-label="Permalink to &quot;Opening the data folder&quot;">​</a></h2><p>In MCPBehindIT: <strong>File</strong> menu (in the menu bar) → <strong>Open Data Folder</strong>. This opens the folder in Finder.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File / Folder</th><th>Purpose</th></tr></thead><tbody><tr><td><code>servers.json</code></td><td>Your MCP server definitions (all servers, enabled or not)</td></tr><tr><td><code>config.json</code></td><td>The generated gateway configuration (recreated on every start)</td></tr><tr><td><code>orchestrator-settings.json</code></td><td>Port, memory limit, CPU limit</td></tr><tr><td><code>license/</code></td><td>Encrypted license storage</td></tr><tr><td><code>oauth-tokens/</code></td><td>OAuth tokens for authenticated servers (Telecontext, etc.)</td></tr><tr><td><code>mcp-local-rag-docs/</code></td><td>Bind-mounted document folder for Local RAG (if configured)</td></tr><tr><td><code>.mindbehind-docker-cli/</code></td><td>Cached Docker CLI binary for catalog servers</td></tr></tbody></table><h2 id="backups" tabindex="-1">Backups <a class="header-anchor" href="#backups" aria-label="Permalink to &quot;Backups&quot;">​</a></h2><p>MCPBehindIT creates automatic backups of <code>servers.json</code>. If the file becomes corrupted, the app restores from the backup and shows a warning banner on the Dashboard.</p><p>To manually back up your configuration, copy <code>servers.json</code> and <code>orchestrator-settings.json</code> to a safe location.</p><h2 id="migrating-to-a-new-mac" tabindex="-1">Migrating to a new Mac <a class="header-anchor" href="#migrating-to-a-new-mac" aria-label="Permalink to &quot;Migrating to a new Mac&quot;">​</a></h2><ol><li>Copy the entire <code>mcp-orchestrator</code> folder to the same path on the new Mac.</li><li>Install MCPBehindIT on the new Mac.</li><li>Launch the app — it picks up your existing servers, settings, and license.</li></ol><div class="warning custom-block"><p class="custom-block-title">License keys are device-bound</p><p>Your license key may need to be re-activated on the new device if the device identifier changes. Contact MindBehind IT if activation fails after migration.</p></div>',16)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
